const crypto = require('crypto');

let rawJob = $input.item.json;
let normalized = {};

// Adapter logic based on source structure
if (rawJob.company_name && rawJob.job_type) { 
  // Remotive format
  normalized.source = 'remotive';
  normalized.external_id = String(rawJob.id);
  normalized.title = rawJob.title;
  normalized.company = rawJob.company_name;
  normalized.location = rawJob.candidate_required_location;
  normalized.remote_type = 'Remote';
  normalized.salary = rawJob.salary;
  normalized.description = rawJob.description;
  normalized.url = rawJob.url;
  normalized.published_at = rawJob.publication_date;
} else if (rawJob.company_name && rawJob.slug) {
  // Arbeitnow format
  normalized.source = 'arbeitnow';
  normalized.external_id = rawJob.slug;
  normalized.title = rawJob.title;
  normalized.company = rawJob.company_name;
  normalized.location = rawJob.location;
  normalized.remote_type = rawJob.remote ? 'Remote' : 'On-site';
  normalized.salary = null;
  normalized.description = rawJob.description;
  normalized.url = rawJob.url;
  normalized.published_at = new Date(rawJob.created_at * 1000).toISOString();
}

// Generate Hash for deduplication
const hashData = normalized.source + '_' + normalized.external_id;
normalized.hash = crypto.createHash('sha256').update(hashData).digest('hex');

return { json: normalized };
